  assert.equal(await conflicting({github: settled.github, repo, number: 4, headSha: head, wait}), true);
  assert.equal(settled.reads.length, 3); assert.deepEqual(waits, [2000, 4000]);
  waits.length = 0;
  const never = reader(computing);
