    for (const fragment of shown) assert.ok(text.includes(fragment), `${name}/${mode}: shows ${fragment}`);
    assert.ok(text.includes(found.lead), `${name}/${mode}: says what this run did`);
    assert.match(text, /\n\n1\. /, `${name}/${mode}: numbered steps`);
